# s03_exact_exceptional.py -- exact orbits over Q(sqrt d) of the finite orbits found numerically in s02;
# group generated by L,R on each (GAP), and characteristic polynomial of T = L_*+R_*+L^-1_*+R^-1_* (flint, exact).
import sys
from fractions import Fraction as Fr
from collections import Counter
from common import *

r2 = QD(0, 1, 2); one2 = QD(1, 0, 2); zero2 = QD(0, 0, 2)
phi = QD(Fr(1, 2), Fr(1, 2), 5); phii = QD(Fr(-1, 2), Fr(1, 2), 5); one5 = QD(1, 0, 5); zero5 = QD(0, 0, 5)
starts = {
    "origin (0,0,0)": (0, 0, 0),
    "(2,2,2)": (2, 2, 2),
    "two-zero (3,0,0) [k=9]": (3, 0, 0),
    "two-zero (1,0,0) [k=1]": (1, 0, 0),
    "k=2: (1,1,1)": (1, 1, 1),
    "k=3: (sqrt2,1,0)": (r2, one2, zero2),
    "k=3: (phi,1/phi,0)": (phi, phii, zero5),
    "k=(5-sqrt5)/2: (1,1/phi,0)": (one5, phii, zero5),
    "k=(5+sqrt5)/2: (1,phi,0)": (one5, phi, zero5),
}
def kval(p): x, y, z = p; return x*x + y*y + z*z - x*y*z
def cyc_type(pm):
    n = len(pm); seen = [False]*n; c = Counter()
    for i in range(n):
        if not seen[i]:
            l = 0; j = i
            while not seen[j]: seen[j] = True; j = pm[j]; l += 1
            c[l] += 1
    return dict(sorted(c.items()))
for name, p0 in starts.items():
    pts, idx = orbit(p0)
    n = len(pts)
    pL, pR = perms(pts, idx)
    o, sd = gap_group_info([pL, pR], n)
    M = T_matrix([pL, pR], n)
    cp, facs = charpoly_factor(M)
    fs = " * ".join("(%s)^%d" % (str(f), e) for f, e in facs)
    print("=== %s : k = %s, orbit size %d" % (name, kval(p0), n))
    print("    L cycle type", cyc_type(pL), " R cycle type", cyc_type(pR))
    print("    group <L,R> on orbit: order %d, structure %s" % (o, sd))
    print("    charpoly(T) =", fs)
    # does the orbit contain all points with these coordinate values on this leaf?  (closure check)
    vals = sorted(set(c for p in pts for c in p), key=float)
    allpts = [(a, b, c) for a in vals for b in vals for c in vals if kval((a, b, c)) == kval(p0)]
    print("    points on this leaf with coordinates in the orbit's value set: %d (orbit has %d)" % (len(allpts), n))
    sys.stdout.flush()
